CREATE COLUMN TABLE "TEST_AP"."OBOC" ("AbsEntry" INTEGER CS_INT NOT NULL , "OpCodeCat" NVARCHAR(30) NOT NULL , "LogInstanc" INTEGER CS_INT DEFAULT 0, "UpdateDate" LONGDATE CS_LONGDATE, "UserSign" SMALLINT CS_INT, "UserSign2" SMALLINT CS_INT, PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OBOC_CATEGORY" ON "TEST_AP"."OBOC" ( "OpCodeCat" ASC )